import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet';
import Header from './Header';

export default function Events() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingEvent, setEditingEvent] = useState(null);
  const [showEditForm, setShowEditForm] = useState(false);


  const updateCount = async (id, action) => {
    try {
      const res = await fetch(`http://localhost:5000/api/events/${id}/${action}`, {
        method: 'POST'
      });
      if (!res.ok) throw new Error('Failed to update');
      const updated = await res.json();
      // Ensure events is an array before mapping
      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.map(e => (e._id === id ? updated.data : e));
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const handleEdit = (event) => {
    setEditingEvent(event);
    setShowEditForm(true);
  };

  const handleUpdate = async (updatedData) => {
    try {
      // Convert date string to Date object if present
      const dataToSend = {
        ...updatedData,
        date: updatedData.date ? new Date(updatedData.date) : undefined,
        capacity: parseInt(updatedData.capacity) || 0
      };

      const res = await fetch(`http://localhost:5000/api/events/${editingEvent._id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(dataToSend)
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.message || 'Failed to update event');
      }

      const result = await res.json();

      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.map(e => (e._id === editingEvent._id ? result.data : e));
      });

      setShowEditForm(false);
      setEditingEvent(null);
      setError(null); // Clear any previous errors
    } catch (err) {
      console.error('Update error:', err);
      setError(err.message);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this event?')) {
      return;
    }

    try {
      const res = await fetch(`http://localhost:5000/api/events/${id}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error('Failed to delete event');

      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.filter(e => e._id !== id);
      });
    } catch (err) {
      setError(err.message);
    }
  };

  useEffect(() => {
    fetch('http://localhost:5000/api/events')
      .then(res => {
        if (!res.ok) {
          throw new Error('Failed to fetch events');
        }
        return res.json();
      })
      .then(data => {
        // Extract events array from API response
        const eventsData = data && data.data ? data.data : [];
        setEvents(eventsData);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching events:', err);
        setError(err.message);
        setEvents([]); // Set to empty array on error
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading events...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  // Additional safety check
  if (!Array.isArray(events)) {
    console.error('Events is not an array:', events);
    return <p style={{ color: 'red' }}>Error: Events data is not properly formatted</p>;
  }

  return (
    <>
      <Helmet>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />
        <meta
          name="description"
          content="EventSync - Campus Events Management"
        />
        <meta name="author" content="SLIIT EventSync Team" />
        <link
          href="https://fonts.googleapis.com/css2?family=Poppins:wght@100;200;300;400;500;600;700;800;900&display=swap"
          rel="stylesheet"
        />
        <title>EventSync - Events Management</title>

        {/* Bootstrap core CSS */}
        <link href="vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet" />

        {/* Additional CSS Files */}
        <link rel="stylesheet" href="assets/css/fontawesome.css" />
        <link rel="stylesheet" href="assets/css/templatemo-574-mexant.css" />
        <link rel="stylesheet" href="assets/css/owl.css" />
        <link rel="stylesheet" href="assets/css/animate.css" />
        <link rel="stylesheet" href="https://unpkg.com/swiper@7/swiper-bundle.min.css" />
      </Helmet>

      <Header />

      <div className="page-heading">
        <div className="container">
          <div className="row">
            <div className="col-lg-12">
              <div className="header-text">
                <h2>Events Management</h2>
                <div className="div-dec"></div>
                <p>Manage and monitor all campus events with real-time updates and analytics</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <section className="contact-us">
        <div className="container">
          <div className="row">
            <div className="col-lg-12">
              <div className="section-heading">
                <h4>Events Dashboard</h4>
                <div className="line-dec"></div>
                <p>View, manage, and track all campus events in one place</p>
              </div>
            </div>
          </div>

          <div className="row mb-4">
            <div className="col-lg-12">
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <span className="badge bg-primary me-2">Total: {events.length}</span>
                  <span className="badge bg-success me-2">Approved: {events.filter(e => e.status === 'Approved').length}</span>
                  <span className="badge bg-warning me-2">Pending: {events.filter(e => e.status === 'Pending').length}</span>
                  <span className="badge bg-danger">Rejected: {events.filter(e => e.status === 'Rejected').length}</span>
                </div>
                <a href="/create-event" className="orange-button">Create New Event</a>
              </div>
            </div>
          </div>

          {error && (
            <div className="row">
              <div className="col-lg-12">
                <div className="alert alert-danger alert-dismissible fade show" role="alert">
                  <strong>Error:</strong> {error}
                  <button type="button" className="btn-close" onClick={() => setError(null)}></button>
                </div>
              </div>
            </div>
          )}

          {showEditForm && (
            <div className="row mb-4">
              <div className="col-lg-12">
                <div className="card">
                  <div className="card-header d-flex justify-content-between align-items-center">
                    <h5 className="mb-0">Edit Event: {editingEvent.title}</h5>
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => {
                      setShowEditForm(false);
                      setEditingEvent(null);
                    }}>
                      <i className="fas fa-times"></i>
                    </button>
                  </div>
                  <div className="card-body">
                    <EventEditForm 
                      event={editingEvent} 
                      onUpdate={handleUpdate} 
                      onCancel={() => {
                        setShowEditForm(false);
                        setEditingEvent(null);
                      }} 
                    />
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="row">
            <div className="col-lg-12">
              <div className="row">
                {events.map(evt => (
                  <div key={evt._id} className="col-lg-12 mb-4">
                    <div className="service-item">
                      <div className="row">
                        <div className="col-lg-8">
                          <div className="right-content">
                            <h4>
                              {evt.title}
                              <span className={`badge ms-2 ${
                                evt.status === 'Approved' ? 'bg-success' : 
                                evt.status === 'Pending' ? 'bg-warning' : 
                                evt.status === 'Rejected' ? 'bg-danger' : 
                                evt.status === 'Completed' ? 'bg-info' : 'bg-secondary'
                              }`}>
                                {evt.status}
                              </span>
                            </h4>

                            {evt.description && (
                              <p>{evt.description}</p>
                            )}

                            <div className="row mb-2">
                              <div className="col-sm-6">
                                <span>
                                  <i className="fas fa-calendar"></i> {new Date(evt.date).toLocaleString()}
                                </span>
                              </div>
                              <div className="col-sm-6">
                                <span>
                                  <i className="fas fa-map-marker-alt"></i> {evt.venue || 'TBA'}
                                </span>
                              </div>
                            </div>

                            <div className="row mb-2">
                              <div className="col-sm-6">
                                <span>
                                  <i className="fas fa-tag"></i> {evt.category}
                                </span>
                              </div>
                              <div className="col-sm-6">
                                <span>
                                  <i className="fas fa-university"></i> {evt.faculty}
                                </span>
                              </div>
                            </div>

                            <div className="row mb-3">
                              <div className="col-sm-4">
                                <span>
                                  <i className="fas fa-users"></i> Capacity: {evt.capacity}
                                </span>
                              </div>
                              <div className="col-sm-4">
                                <span>
                                  <i className="fas fa-user-check"></i> Registered: {evt.registrationCount || 0}
                                </span>
                              </div>
                              <div className="col-sm-4">
                                <span>
                                  <i className="fas fa-clipboard-check"></i> Attended: {evt.attendanceCount || 0}
                                </span>
                              </div>
                            </div>

                            {evt.tags && evt.tags.length > 0 && (
                              <div className="mb-2">
                                {evt.tags.map((tag, index) => (
                                  <span key={index} className="badge bg-light text-dark me-1">
                                    #{tag}
                                  </span>
                                ))}
                              </div>
                            )}

                            {evt.organizer && (
                              <div className="mb-2">
                                <span>
                                  <i className="fas fa-user"></i> Organizer: {evt.organizer}
                                  {evt.organizerEmail && ` <${evt.organizerEmail}>`}
                                </span>
                              </div>
                            )}
                          </div>
                        </div>

                        <div className="col-lg-4">
                          <div className="left-image">
                            <div className="d-flex flex-column gap-2">
                              <button
                                className="orange-button"
                                onClick={() => updateCount(evt._id, 'register')}
                              >
                                <i className="fas fa-user-plus"></i> Register
                              </button>
                              <button
                                className="orange-button"
                                onClick={() => updateCount(evt._id, 'checkin')}
                              >
                                <i className="fas fa-check-circle"></i> Check‑In
                              </button>
                              <button
                                className="orange-button"
                                onClick={() => handleEdit(evt)}
                              >
                                <i className="fas fa-edit"></i> Edit
                              </button>
                              <button
                                className="orange-button"
                                onClick={() => handleDelete(evt._id)}
                              >
                                <i className="fas fa-trash"></i> Delete
                              </button>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer>
        <div className="container">
          <div className="row">
            <div className="col-lg-12">
              <p>
                © 2026 EventSync – Campus Event Management & QR Analytics Platform. All Rights Reserved.
                <br />
                Developed for SLIIT Academic Project | Designed for Smart Campus Event Operations
              </p>
            </div>
          </div>
        </div>
      </footer>
    </>
  );
}

// EventEditForm Component
function EventEditForm({ event, onUpdate, onCancel }) {
  const [formData, setFormData] = useState({
    title: event.title || '',
    description: event.description || '',
    category: event.category || '',
    faculty: event.faculty || '',
    venue: event.venue || '',
    capacity: event.capacity || '',
    date: event.date ? new Date(event.date).toISOString().slice(0, 16) : '',
    status: event.status || 'Pending'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onUpdate(formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Title</label>
            <input
              type="text"
              className="form-control"
              name="title"
              value={formData.title}
              onChange={handleChange}
              required
            />
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Category</label>
            <select
              className="form-control"
              name="category"
              value={formData.category}
              onChange={handleChange}
              required
            >
              <option value="">Select Category</option>
              <option value="Academic">Academic</option>
              <option value="Sports">Sports</option>
              <option value="Cultural">Cultural</option>
              <option value="Technical">Technical</option>
              <option value="Workshop">Workshop</option>
              <option value="Seminar">Seminar</option>
            </select>
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Faculty</label>
            <select
              className="form-control"
              name="faculty"
              value={formData.faculty}
              onChange={handleChange}
              required
            >
              <option value="">Select Faculty</option>
              <option value="Computing">Computing</option>
              <option value="Engineering">Engineering</option>
              <option value="Business">Business</option>
              <option value="Science">Science</option>
              <option value="Architecture">Architecture</option>
              <option value="Graduate Studies">Graduate Studies</option>
            </select>
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Venue</label>
            <input
              type="text"
              className="form-control"
              name="venue"
              value={formData.venue}
              onChange={handleChange}
            />
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Capacity</label>
            <input
              type="number"
              className="form-control"
              name="capacity"
              value={formData.capacity}
              onChange={handleChange}
              min="1"
              required
            />
          </div>
        </div>
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Date & Time</label>
            <input
              type="datetime-local"
              className="form-control"
              name="date"
              value={formData.date}
              onChange={handleChange}
              required
            />
          </div>
        </div>
      </div>

      <div className="row">
        <div className="col-md-6">
          <div className="form-group mb-3">
            <label className="form-label">Status</label>
            <select
              className="form-control"
              name="status"
              value={formData.status}
              onChange={handleChange}
            >
              <option value="Pending">Pending</option>
              <option value="Approved">Approved</option>
              <option value="Rejected">Rejected</option>
              <option value="Cancelled">Cancelled</option>
              <option value="Completed">Completed</option>
            </select>
          </div>
        </div>
      </div>

      <div className="form-group mb-3">
        <label className="form-label">Description</label>
        <textarea
          className="form-control"
          name="description"
          value={formData.description}
          onChange={handleChange}
          rows="3"
        />
      </div>

      <div className="d-flex gap-2">
        <button type="submit" className="btn btn-primary">
          Update Event
        </button>
        <button type="button" className="btn btn-secondary" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </form>
  );
}
